const D = { density:.55, curl:.5, energy:.62, speed:1, scale:1, hue:275, x:.5, y:.9, style:'delta', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const clp = (v,a,b)=>Math.max(a,Math.min(b,v));
const wh = h => ((h%360)+360)%360;
const st = P.style;
const sec = K.section|0;
const intn = (K.intensity!=null?K.intensity:.6);

// ---- style config: each is a distinct rendering philosophy, not just a palette ----
// gH,gS,gB=ground · add=additive glow vs flat BLEND · h0->h1=hue ramp by orbit length · sat/bri=stroke
// blur=bloom weight · wmul=stroke mass · tip=ember stipple at strand ends · glow=bloom css · glH=glint hue
let cfg;
if (st==='coral')       cfg={gH:185,gS:60,gB:10, add:true,  h0:180,h1:330, sat:80, blur:2, bri:52, wmul:1.7, tip:false, glow:'rgba(120,230,220,0.7)',  glH:320}; // chunky low-bloom coral mass
else if (st==='autumn') cfg={gH:18, gS:66,gB:10, add:true,  h0:6,  h1:48,  sat:90, blur:5, bri:58, wmul:1.0, tip:true,  glow:'rgba(255,150,60,0.85)',  glH:42};  // ember strands w/ glowing tip stipple
else if (st==='bio')    cfg={gH:210,gS:74,gB:6,  add:true,  h0:165,h1:290, sat:92, blur:9, bri:66, wmul:0.7, tip:false, glow:'rgba(120,255,220,0.9)',  glH:175}; // thin heavy-bloom electric filaments, deep-sea
else if (st==='ink')    cfg={gH:40, gS:10,gB:86, add:false, h0:28, h1:34,  sat:12, blur:0, bri:14, wmul:1.0, tip:false, glow:'rgba(0,0,0,0)',          glH:30};  // flat sumi mono, no glow, dry lines
else /* delta */        cfg={gH:268,gS:55,gB:11, add:true,  h0:282,h1:46,  sat:86, blur:4, bri:56, wmul:1.0, tip:false, glow:'rgba(255,205,120,0.85)', glH:50};  // luminous violet->gold delta

// ---- persistent accumulation buffer (keyed on size) ----
if (!S.buf || S.bufKey !== width+'x'+height){
  if (S.buf) S.buf.remove();
  S.buf = createGraphics(width, height);
  S.buf.colorMode(HSB,360,100,100,100);
  S.buf.background(cfg.gH,cfg.gS,cfg.gB);
  S.bufKey = width+'x'+height; S.gk = st; S.count=0; S.recent=[]; S.ri=0; S.acc=0;
}
if (S.gk !== st){ S.gk = st; S.buf.background(cfg.gH,cfg.gS,cfg.gB); S.recent=[]; }
const buf = S.buf;

// seed-deterministic hash (no p5 random)
const fh = (a,b)=>{ const s=Math.sin(a*127.1 + b*311.7 + P.seed*74.7)*43758.5453; return s-Math.floor(s); };

// ---- continuous soft fade: churn without a hard clear (no strobe) ----
const fade = st==='ink' ? 5.5 : (3.0 + (1-intn)*2.4);
buf.push(); buf.noStroke(); buf.fill(cfg.gH,cfg.gS,cfg.gB, fade); buf.rect(0,0,width,height); buf.pop();

// ---- geometry ----
const rootX = clp(P.x,0.06,0.94)*width, rootY = clp(P.y,0.06,0.98)*height;
const seg = u*0.0062*clp(P.scale,0.4,2.4);
const cr = clp(P.curl,0.05,1.05)*0.52;
const evenA = cr*0.6, oddA = cr;                  // even bends one way (gently), odd the other (sharply)
const baseAng = Math.PI/2;                        // grow "up" in math coords
const fanSpread = 0.5;                            // per-strand apex fan so the delta spreads
const hShift = (P.hue - 275);

// ---- how many new strands stream in this frame (accumulator so growth never fully stalls) ----
S.acc += clp((0.35 + P.density*3.0)*(0.40+intn)*(0.35+P.speed*0.9) + A.bass*3.5, 0.05, 14);
let nAdd = Math.floor(S.acc); S.acc -= nAdd; if (nAdd>14) nAdd=14;
const Nrange = 200 + Math.round(P.density*1400);  // integer pool 200..1600
const nbase = 2 + (((P.seed*53 + sec*89)>>>0) % 997);

buf.push();
buf.blendMode(cfg.add ? ADD : BLEND);
buf.noFill(); buf.strokeCap(ROUND); buf.strokeJoin(ROUND);
for (let s=0; s<nAdd; s++){
  const gi = S.count++;
  const n = 2 + ((nbase + gi) % Nrange);
  // forward Collatz (hailstone) sequence n .. 1, then reverse to walk out from the shared root(1)
  const seq=[]; let v=n, guard=0;
  while (v>1 && guard++<600){ seq.push(v); v = (v%2===0) ? v/2 : 3*v+1; }
  seq.push(1); seq.reverse();
  const L = seq.length, norm = clp((L-5)/95, 0, 1);
  const jit = (fh(gi,1)-0.5)*0.10;
  const mir = (gi & 1) ? -1 : 1;                  // alternate strands to each side -> two-sided delta fills frame
  let ang = baseAng + (fh(gi,2)-0.5)*fanSpread;
  let x=0, y=0;
  const pts=[[rootX, rootY]];
  const cap = Math.min(L, 170);
  for (let k=0;k<cap;k++){
    const even = (seq[k]%2===0);
    ang += even ? evenA*(1+jit) : -oddA*(1+jit);
    x += Math.cos(ang)*seg; y += Math.sin(ang)*seg;
    pts.push([rootX + x*mir, rootY - y]);
  }
  // hue by orbit length: young(short)->violet, old(long)->gold (delta ramp 282->46); slow section drift = palette evolves over minutes
  const h = wh(cfg.h0 + norm*(cfg.h1-cfg.h0) + hShift*0.6 + sec*5);
  const sb = clp(cfg.bri + norm*30, 10, 100);
  const sa = cfg.add ? clp(11 + P.energy*15, 6, 34) : clp(24 + P.energy*22, 12, 60);
  if (cfg.blur>0){ buf.drawingContext.shadowBlur = cfg.blur*(0.5+P.energy*0.9); buf.drawingContext.shadowColor = cfg.glow; }
  buf.stroke(h, cfg.sat, sb, sa);
  buf.strokeWeight((0.8 + (1-norm)*0.7) * (0.7+P.scale*0.35) * cfg.wmul);
  buf.beginShape();
  for (let q=0;q<pts.length;q++) buf.vertex(pts[q][0], pts[q][1]);
  buf.endShape();
  // ember stipple: a hot glowing mote at the strand end (autumn foliage/ember texture)
  if (cfg.tip && pts.length>2){ const e=pts[pts.length-1];
    buf.noStroke(); buf.fill(wh(h+8), cfg.sat-15, 100, clp(28+P.energy*30,10,70));
    buf.circle(e[0], e[1], u*(0.004+0.006*norm)); buf.noFill(); }
  if (cfg.blur>0) buf.drawingContext.shadowBlur = 0;
  if (pts.length>4){ S.recent[S.ri % 30] = { p:pts, ph:fh(gi,3) }; S.ri++; }
}
buf.blendMode(BLEND); buf.pop();

// ---- display the delta with a slow, non-repeating K.t drift (motion floor) ----
const dx = Math.sin(K.t*0.13)*u*0.02, dy = Math.cos(K.t*0.10)*u*0.015;
const rot = 0.02*Math.sin(K.t*0.05);
const scb = 1.14 + 0.02*Math.sin(K.t*0.07);
push();
translate(dx, dy);
translate(width/2, height/2); scale(scb); rotate(rot); translate(-width/2, -height/2);
if (P.alpha < 100) tint(0,0,100,P.alpha);
image(buf, 0, 0, width, height);
noTint();

// ---- live current: glints streaming along the newest strands (continuous, silence-safe) ----
if (st !== 'ink'){
  blendMode(ADD); noStroke();
  const gc = S.recent, R = gc.length, flow = 0.10 + P.speed*0.06;
  for (let i=0;i<R;i++){ const e=gc[i]; if(!e||!e.p) continue;
    const p=e.p, np=p.length;
    const tt = ((K.t*flow + e.ph + i*0.13) % 1 + 1) % 1;
    const idx = clp(Math.floor(tt*(np-1)), 0, np-1);
    const q = p[idx];
    const pulse = 0.5+0.5*Math.sin(K.t*3 + i*0.7);
    const sz = u*(0.006+0.008*pulse)*(0.7+P.energy) + A.treble*u*0.012;
    fill(wh(cfg.glH + (i%7-3)*3), 52, 100, (12 + pulse*20)*(0.4+P.energy) + A.rms*40);
    circle(q[0], q[1], sz);
  }
  // root mouth glow — breathes on the beat, anchors the delta
  const gpulse = 0.5 + 0.4*Math.sin(K.t*1.3) + K.pulse*0.5 + A.bass*0.6;
  fill(wh(cfg.glH), 40, 100, 10*(0.5+P.energy)*clp(gpulse,0,1.6));
  circle(rootX, rootY, u*0.09*(0.7+0.3*gpulse));
  blendMode(BLEND);
}
pop();
blendMode(BLEND);
